application.css:
* { box-sizing: border-box; }

:root {
  --ink: #20243a;
  --muted: #85899f;
  --purple: #7161ef;
  --purple-dark: #5b4bd6;
  --line: #ececf4;
  --soft: #f7f7fc;
  --coral: #f47f78;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 28px 18px;
  color: var(--ink);
  background: linear-gradient(135deg, #f0efff 0%, #fbf9f7 55%, #fff1ed 100%);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

.app-shell { width: 100%; max-width: 620px; }
.todo-card {
  background: rgba(255,255,255,.94);
  border: 1px solid rgba(255,255,255,.8);
  border-radius: 26px;
  padding: clamp(25px, 6vw, 46px);
  box-shadow: 0 22px 60px rgba(57, 49, 108, .13);
}
.app-header { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; margin-bottom: 30px; }
.eyebrow { color: var(--purple); font-size: 11px; font-weight: 800; letter-spacing: .15em; }
h1 { margin: 7px 0 5px; font-size: clamp(32px, 6vw, 46px); letter-spacing: -.05em; line-height: 1; }
.subtitle { margin: 0; color: var(--muted); font-size: 14px; }
.count-badge { min-width: 63px; padding: 12px 13px; border-radius: 15px; color: var(--purple); background: #f0eeff; text-align: center; }
.count-badge strong { display: block; font-size: 22px; line-height: 1; }
.count-badge span { font-size: 11px; font-weight: 700; }
.task-form { display: flex; gap: 10px; margin-bottom: 36px; }
.task-form input { min-width: 0; flex: 1; border: 1px solid var(--line); border-radius: 13px; padding: 15px 16px; color: var(--ink); background: var(--soft); outline: none; font: inherit; transition: .2s; }
.task-form input:focus { border-color: var(--purple); box-shadow: 0 0 0 4px rgba(113,97,239,.12); background: white; }
.task-form button { border: 0; border-radius: 13px; padding: 0 18px; color: white; background: var(--purple); cursor: pointer; font: 700 14px inherit; box-shadow: 0 7px 14px rgba(113,97,239,.22); transition: .2s; }
.task-form button:hover { background: var(--purple-dark); transform: translateY(-1px); }
.task-form button span { margin-left: 6px; font-size: 18px; vertical-align: -1px; }
.list-heading { display: flex; align-items: center; gap: 13px; margin-bottom: 13px; }
.list-heading h2 { margin: 0; font-size: 15px; letter-spacing: .02em; }
.list-decoration { width: 34px; height: 3px; border-radius: 4px; background: var(--coral); }
.task-list { display: grid; gap: 10px; }
.task { display: flex; align-items: center; gap: 12px; min-height: 59px; padding: 10px 12px; border: 1px solid var(--line); border-radius: 14px; background: white; animation: appear .25s ease-out; }
.task-text { flex: 1; overflow-wrap: anywhere; font-size: 15px; }
.task[data-completed="true"] .task-text { color: #a6a8b6; text-decoration: line-through; }
.complete-button { width: 25px; height: 25px; flex: 0 0 25px; border: 2px solid #d8d8e5; border-radius: 50%; background: white; cursor: pointer; position: relative; }
.task[data-completed="true"] .complete-button { border-color: var(--purple); background: var(--purple); }
.task[data-completed="true"] .complete-button::after { content: "✓"; position: absolute; inset: -1px 0 0; color: white; font-size: 15px; font-weight: 800; }
.delete-button { border: 0; padding: 7px; color: #b7b8c5; background: transparent; cursor: pointer; font-size: 18px; line-height: 1; }
.delete-button:hover { color: var(--coral); }
.empty-message { margin: 22px 0 4px; color: var(--muted); text-align: center; font-size: 13px; }
footer { margin-top: 18px; color: #9293a5; text-align: center; font-size: 12px; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@keyframes appear { from { opacity: 0; transform: translateY(-5px); } to { opacity: 1; transform: translateY(0); } }
@media (max-width: 430px) { .task-form { flex-direction: column; } .task-form button { padding: 13px; } }

application.javascript:
document.addEventListener('DOMContentLoaded', function () {
  const form = document.getElementById('task-form');
  const input = document.getElementById('task-input');
  const list = document.getElementById('task-list');
  const count = document.querySelector('[data-testid="incomplete-count"]');
  const emptyMessage = document.getElementById('empty-message');
  let tasks = [];

  function render() {
    list.textContent = '';
    tasks.forEach(function (task) {
      const item = document.createElement('div');
      item.className = 'task';
      item.dataset.testid = 'task';
      item.dataset.completed = String(task.completed);

      const complete = document.createElement('button');
      complete.type = 'button';
      complete.className = 'complete-button';
      complete.dataset.testid = 'task-complete';
      complete.setAttribute('aria-label', task.completed ? 'Mark task incomplete' : 'Mark task complete');
      complete.addEventListener('click', function () {
        task.completed = !task.completed;
        render();
      });

      const text = document.createElement('span');
      text.className = 'task-text';
      text.dataset.testid = 'task-text';
      text.textContent = task.text;

      const remove = document.createElement('button');
      remove.type = 'button';
      remove.className = 'delete-button';
      remove.dataset.testid = 'task-delete';
      remove.setAttribute('aria-label', 'Delete task');
      remove.textContent = '×';
      remove.addEventListener('click', function () {
        tasks = tasks.filter(function (current) { return current.id !== task.id; });
        render();
      });

      item.append(complete, text, remove);
      list.appendChild(item);
    });
    count.textContent = String(tasks.filter(function (task) { return !task.completed; }).length);
    emptyMessage.hidden = tasks.length > 0;
  }

  form.addEventListener('submit', function (event) {
    event.preventDefault();
    const text = input.value.trim();
    if (!text) return;
    tasks.push({ id: Date.now() + Math.random(), text: text, completed: false });
    input.value = '';
    render();
    input.focus();
  });

  render();
});
